INSERT INTO `movie` VALUES (1,'TEE YOD: Quỷ Ăn Tạng Phần 3','ธี่หยด 3','Tiếp nối mạch phim kinh dị Thái Lan ăn khách, phần 3 đưa gia đình Yak trở lại đối mặt với thế lực tà ác mới. Khi cô em út Yee bị thế lực quỷ dữ bí ẩn bắt cóc, Yak và những người bạn buộc phải dấn thân vào một hành trình tuyệt vọng để giải cứu cô. Cuộc tìm kiếm dẫn họ đến Bong Sa Noh Bian — một khu rừng bị ma ám đầy rẫy những bí mật đen tối và linh hồn báo thù. Tại đây, họ không chỉ chiến đấu với những sinh vật siêu nhiên mà còn phải đối mặt với nguồn gốc của linh hồn Hắc ám. Sự sinh tồn trở thành cuộc chiến chống lại những thế lực vượt ngoài tầm kiểm soát của con người.',104,'8.2','T16 (Từ đủ 16 tuổi trở lên)','2025-10-10','2025-11-20','2025-10-08','/assets/images/movies/tee_yod_quy_an_tang_phan_3/poster_doc.jpg','/assets/images/movies/tee_yod_quy_an_tang_phan_3/poster_ngang.jpg','https://youtu.be/DXV3x2Htbyg?si=sb8URmHmGf2CWVVw',1,'now','Tiếng Thái | Phụ đề Tiếng Việt'),(2,'Cục Vàng Của Ngoại','Cục Vàng Của Ngoại','Phim khai thác chủ đề tình cảm gia đình ấm áp nhưng cũng đầy những day dứt giữa bà và cháu. Thông qua những lát cắt đời thường, bộ phim gợi cho người xem những ký ức về ông bà, cha mẹ và chính mình. Mỗi diễn viên, đặc biệt là Việt Hương và Hồng Đào, đều bùng nổ cảm xúc, mang đến một món quà tình cảm nhẹ nhàng mà rưng rức cho khán giả.',119,'8.0','T13 (Từ đủ 13 tuổi trở lên)','2025-10-17','2025-11-27','2025-10-16','/assets/images/movies/cuc_vang_cua_ngoai/poster_doc.jpg','/assets/images/movies/cuc_vang_cua_ngoai/poster_ngang.jpg','https://youtu.be/_cj77qa_wMc?si=N6ONr9MfZmjNnkhr',1,'now','Tiếng Việt | Phụ đề Tiếng Anh'),(3,'Nhà Ma Xó','Nhà Ma Xó','Phim xoay quanh gia đình bà Hiền, người mẹ đơn thân nuôi ba người con sau tai nạn của chồng. Mọi chuyện kỳ quái bắt đầu khi người con trai giữa vớt được một chiếc khạp sành đậy kín nắp khi đang thả lưới bắt cá dưới sông. Từ đó, hàng loạt hiện tượng bí ẩn, rùng rợn liên tiếp xảy ra, làm rạn nứt các mối quan hệ trong gia đình và dần hé lộ những bí mật động trời bị chôn giấu từ lâu.',108,'8.0','T16 (Từ đủ 16 tuổi trở lên)','2025-10-24','2025-12-04','2025-10-22','/assets/images/movies/nha_ma_xo/poster_doc.jpg','/assets/images/movies/nha_ma_xo/poster_ngang.jpg','https://youtu.be/ZEq0D-Y0VeU?si=bdGOVAfAhJyRYNGe',1,'now','Tiếng Việt | Phụ đề Tiếng Anh'),(4,'Phá Đám Sinh Nhật Mẹ','Phá Đám Sinh Nhật Mẹ','Y Đức - một người con trai bất hiếu đang bị giang hồ đe dọa. Trong lúc túng quẫn, anh nảy ra một kế hoạch điên rồ: tổ chức đám ma giả cho chính mẹ mình để lừa tiền bảo hiểm. Tuy nhiên, kế hoạch này liên tục bị \"phá đám\" bởi hàng loạt những vị khách không mời và những tình huống dở khóc dở cười. Trớ trêu thay, ngày anh đưa mẹ vào hòm lại chính là ngày sinh nhật lần thứ 60 của bà.',91,'7.8','T16 (Từ đủ 16 tuổi trở lên)','2025-10-31','2025-12-11',NULL,'/assets/images/movies/pha_dam_sinh_nhat_me/poster_doc.jpg','/assets/images/movies/pha_dam_sinh_nhat_me/poster_ngang.jpg','https://youtu.be/auO0QxMjTlc?si=k8hCvuxead91UzaW',1,'now','Tiếng Việt | Phụ đề Tiếng Anh'),(5,'Cải Mã','Cải Mã','Đại gia đình ông Quang, những người trở về quê để thực hiện nghi lễ cải táng (bốc mộ) đã bị trì hoãn quá lâu. Tưởng chừng đây chỉ là một nghĩa vụ hậu sự bình thường, nhưng việc làm này vô tình khơi dậy vòng xoáy nghiệp báo truyền đời và những bí mật đen tối bị chôn vùi. Hàng loạt tai ương và hiện tượng bí ẩn liên tục giáng xuống các thành viên trong gia đình, đẩy họ vào sự sợ hãi tột độ.',115,'8.6','T16 (Từ đủ 16 tuổi trở lên)','2025-10-31','2025-12-11','2025-10-29','/assets/images/movies/cai_ma/poster_doc.jpg','/assets/images/movies/cai_ma/poster_ngang.jpg','https://youtu.be/KxvLXJqFCPY?si=_B4HuIY_0IUYx9ZO',1,'now','Tiếng Việt | Phụ đề Tiếng Anh'),(6,'Bí Mật Sau Bữa Tiệc','Anniversary','Bộ phim mở đầu bằng bữa tiệc kỷ niệm 25 năm ngày cưới ấm áp của Ellen và Paul Taylor, nhưng mọi thứ nhanh chóng rạn nứt khi con trai họ giới thiệu vị hôn thê mới là Liz. Liz, một cựu sinh viên có tư tưởng cực đoan của Ellen, mang theo một phong trào chính trị gây tranh cãi tên là \"Sự Thay Đổi\" (The Change) xâm nhập vào gia đình. Xuyên suốt năm năm đầy biến động, bộ phim phơi bày những rạn nứt thế hệ, sự đấu đá quyền lực và những phản bội riêng tư khi lòng trung thành của các thành viên gia đình bị thử thách bởi bối cảnh chính trị ngày càng hỗn loạn và độc đoán của đất nước. ',112,'7.6','T18 (Từ đủ 18 tuổi trở lên)','2025-10-31','2025-12-11',NULL,'/assets/images/movies/bi_mat_sau_bua_tiec/poster_doc.jpg','/assets/images/movies/bi_mat_sau_bua_tiec/poster_ngang.jpg','https://youtu.be/kW4sYsN1_cc?si=6YXhuGXOPEsARdRx',1,'now','Tiếng Anh | Phụ đề Tiếng Việt'),(7,'Bịt Mắt Bắt Nai','Bịt Mắt Bắt Nai','Một nhóm bạn trẻ vô tình dấn thân vào trò chơi sinh tồn đầy ám ảnh sau khi bước vào một ngôi nhà bí ẩn. Khi trò chơi \"bịt mắt\" không còn là trò đùa, mỗi bước đi sai lầm đều phải trả giá bằng máu và nước mắt. Tình bạn, tình yêu và lòng thù hận đan xen, đẩy các nhân vật vào những lựa chọn sinh tử.',92,'7.5','T16 (Từ đủ 16 tuổi trở lên)','2025-10-31','2025-12-11',NULL,'/assets/images/movies/bit_mat_bat_nai/poster_doc.jpg','/assets/images/movies/bit_mat_bat_nai/poster_ngang.jpg','https://youtu.be/AVm6gVRaOQE?si=0UBBnQy9h9hzq3rp',1,'now','Tiếng Việt | Phụ đề Tiếng Anh'),(8,'Điện Thoại Đen 2','The Black Phone 2','Bốn năm sau khi thoát khỏi tên sát nhân hàng loạt The Grabber, Finney Blake và cô em gái có năng lực ngoại cảm Gwen đang cố gắng cân bằng lại cuộc sống bình thường của mình. Tuy nhiên, ký ức kinh hoàng vẫn ám ảnh họ. Mọi chuyện chưa dừng lại khi Gwen bắt đầu gặp những giấc mơ khủng khiếp và nhận được các cuộc gọi bí ẩn từ một chiếc điện thoại đen không dây, liên quan đến những vụ mất tích mới tại khu cắm trại hồ Alpine. Để tìm ra sự thật và chấm dứt chuỗi bi kịch, hai anh em buộc phải đối mặt với sự trở lại đầy thù hận của linh hồn The Grabber, kẻ thề sẽ trả thù Finney vì đã kết liễu mạng sống của hắn ở phần trước. ',114,'8.6','T18 (Từ đủ 18 tuổi trở lên)','2025-10-31','2025-12-11','2025-10-25','/assets/images/movies/dien_thoai_den_2/poster_doc.jpg','/assets/images/movies/dien_thoai_den_2/poster_ngang.jpg','https://youtu.be/K4Ml_YDwfoU?si=sH0damf21UmYmt8n',1,'now','Tiếng Anh | Phụ đề Tiếng Việt'),(9,'Trái Tim Què Quặt','Trái Tim Què Quặt','Phim được lấy cảm hứng từ tiểu thuyết kinh điển À Cloche Coeur của nhà văn Pháp Catherine Arley, và xoay quanh một vụ án mạng tàn bạo làm chấn động thị trấn yên bình Đà Lạt. Khi thi thể người phụ nữ bị sát hại dã man được phát hiện, mọi nghi ngờ đổ dồn vào Sơn, người được cho là tình nhân của nạn nhân. Bên cạnh Sơn là Triết, anh trai anh và một nhà điêu khắc danh tiếng. Câu chuyện về những tình yêu méo mó, sự chiếm hữu và thao túng, liệu một tình yêu tưởng chừng hoàn hảo có thể che giấu những góc khuất đáng sợ nào không? ',102,'8.2','T18 (Từ đủ 18 tuổi trở lên)','2025-11-07','2025-12-18','2025-11-06','/assets/images/movies/trai_tim_que_quat/poster_doc.jpg','/assets/images/movies/trai_tim_que_quat/poster_ngang.jpg','https://youtu.be/iMjjqsP9_nk?si=lH7b209c5hJd715A',1,'now','Tiếng Việt | Phụ đề Tiếng Anh'),(10,'Tình Người Duyên Ma','Nak Rak Mak','Lấy cảm hứng từ truyền thuyết dân gian Thái Lan về hồn ma Mae Nak, Tình Người Duyên Ma: Nhắm \"Mak\" Yêu Luôn kể câu chuyện tình vượt thời gian giữa nàng Nak và chàng Mak. Xuyên không đến 200 năm sau, Nak bất ngờ được vào vai nữ chính trong chính bộ phim về truyền thuyết của mình. Tình cờ thay, vai nam chính lại được thủ bởi Mak - lúc này đã là một nam diễn viên nổi tiếng toàn quốc. Ở đây, Nak phải chinh phục lại trái tim Mak trong vòng 30 ngày mà không được dùng đến ma lực, để có thể ở bên anh trọn đời trọn kiếp.',104,'8.7','T13 (Từ đủ 13 tuổi trở lên)','2025-11-07','2025-12-18','2025-11-08','/assets/images/movies/tinh_nguoi_duyen_ma/poster_doc.jpg','/assets/images/movies/tinh_nguoi_duyen_ma/poster_ngang.jpg','https://youtu.be/TpUvaW2ymeg?si=A6jdTCUr-R7ncon7',1,'now','Tiếng Thái | Phụ đề Tiếng Việt'),(11,'Thai Chiêu Tài','Thai Chiêu Tài','Một nhóm bạn trẻ, vì nợ nần và túng quẫn, đã tìm đến một thầy bùa để thỉnh \"Thai Chiêu Tài\" – một loại bùa ngải được cho là mang lại sự giàu có nhanh chóng. Tuy nhiên, sự giàu có không đến dễ dàng khi họ phải đối mặt với những lời nguyền rùng rợn và thế lực tà ác đi kèm với bùa ngải. Họ bị cuốn vào một vòng xoáy của sự sợ hãi, phải tìm mọi cách để thoát khỏi sự đeo bám của linh hồn quỷ dữ và bảo vệ mạng sống của mình.',104,'8.2','T18 (Từ đủ 18 tuổi trở lên)','2025-11-07','2025-12-18','2025-11-05','/assets/images/movies/thai_chieu_tai/poster_doc.jpg','/assets/images/movies/thai_chieu_tai/poster_ngang.jpg','https://youtu.be/4QLv7aJq1Wg?si=c9td6U9QRjNkx-Lk',1,'now','Tiếng Việt | Phụ đề Tiếng Anh'),(12,'Quái Thú Vô Hình: Vùng Đất Chết Chóc','Predator: Badlands','Dek, một chiến binh Predator trẻ tuổi bị ruồng bỏ, dấn thân vào hành trình săn lùng một sinh vật nguy hiểm trên hành tinh Genna để khôi phục danh dự. Anh tình cờ gặp Thia, một người máy bị hư hại của tập đoàn Weyland-Yutani, và họ buộc phải hợp tác để sinh tồn. Cả hai không chỉ đối mặt với kẻ thù tối thượng mà còn phải chống lại các mối đe dọa từ hành tinh khắc nghiệt và lực lượng truy đuổi của con người.',107,'8.8','T16 (Từ đủ 16 tuổi trở lên)','2025-11-07','2025-12-18',NULL,'/assets/images/movies/quai_thu_vo_hinh_vung_dat_chet_choc/poster_doc.jpg','/assets/images/movies/quai_thu_vo_hinh_vung_dat_chet_choc/poster_ngang.jpg','https://youtu.be/AzBi73ddou4?si=8UW6wY8PeQAa8pqB',1,'now','Tiếng Anh | Phụ đề Tiếng Việt'),(13,'Lọ Lem Chơi Ngải','Kitab Sijjin & Illiyyin','Yuli, một cô gái mồ côi phải sống như người hầu trong gia đình Ambar và chịu đựng sự sỉ nhục suốt nhiều năm. Quá uất hận, Yuli quyết tâm trả thù bằng cách tàn nhẫn nhất: tìm đến thầy pháp yểm bùa hắc ám để hủy hoại từng thành viên trong gia đình Ambar. Cô thực hiện một nghi lễ ghê rợn là ghi tên những người bị nguyền rủa lên xác chết vừa qua đời. Tuy nhiên, Yuli có một tuần để hoàn tất giao kèo với quỷ dữ, nếu không sẽ phải gánh chịu hậu quả khủng khiếp, đẩy cô vào vòng xoáy sinh tử đầy rùng rợn. ',98,'8.1','T18 (Từ đủ 18 tuổi trở lên)','2025-11-07','2025-12-18',NULL,'/assets/images/movies/lo_lem_choi_ngai/poster_doc.jpg','/assets/images/movies/lo_lem_choi_ngai/poster_ngang.jpg','https://youtu.be/T6ty2iYxeT4?si=xlXBWoyFeKR_-HnM',1,'now','Tiếng Indonesia | Phụ đề Tiếng Việt'),(14,'Trốn Chạy Tử Thần','The Running Man','Lấy bối cảnh tương lai hỗn loạn, Ben Richards, một người cha túng quẫn, tuyệt vọng tìm tiền cứu con gái bệnh nặng. Không còn cách nào khác, Ben buộc phải tham gia vào \"The Running Man\" – một trò chơi sinh tử đẫm máu phát sóng trực tiếp toàn quốc. Anh trở thành con mồi bị săn đuổi bởi những \"thợ săn\" chuyên nghiệp. Cuộc trốn chạy của anh dần biến thành một cuộc chiến chống lại sự thao túng truyền thông và xã hội độc hại.',133,'8.7','T18 (Từ đủ 18 tuổi trở lên)','2025-11-14','2025-12-25',NULL,'/assets/images/movies/tron_chay_tu_than/poster_doc.jpg','/assets/images/movies/tron_chay_tu_than/poster_ngang.jpg','https://youtu.be/A0HOepo6xQI?si=Vye5CeoQ6Cq_w3tI',1,'now','Tiếng Anh | Phụ đề Tiếng Việt'),(15,'Truy Tìm Long Diên Hương','Truy Tìm Long Diên Hương','Một nhóm người với những tính cách khác biệt tình cờ đụng độ và phải hợp tác trong một phi vụ bất đắc dĩ. Mục tiêu của họ là truy tìm Long Diên Hương, một loại báu vật quý giá và cực hiếm được mệnh danh là \"vàng nổi\". Hành trình tìm kiếm đầy rẫy những tình huống dở khóc dở cười, những pha hành động kịch tính và những âm mưu bất ngờ.',103,'8.5','T16 (Từ đủ 16 tuổi trở lên)','2025-11-14','2025-12-25','2025-11-12','/assets/images/movies/truy_tim_long_dien_huong/poster_doc.jpg','/assets/images/movies/truy_tim_long_dien_huong/poster_ngang.jpg','https://youtu.be/-wmBoUIJ9uo?si=PGlY2d7zYWRfbcOO',1,'now','Tiếng Việt | Phụ đề Tiếng Anh'),(16,'G-Dragon In Cinema','G-DRAGON IN CINEMA [Übermensch]','\"G-Dragon In Cinema\" là một bộ phim tài liệu âm nhạc Hàn Quốc ghi lại hành trình lưu diễn thế giới \"ACT III, M.O.T.T.E.\" của nghệ sĩ G-Dragon (Kwon Ji-yong). Với tiêu đề phụ [Übermensch], bộ phim khám phá sâu sắc hai mặt con người anh: G-Dragon hào nhoáng trên sân khấu và Kwon Ji-yong đời thường, nội tâm. Khán giả được chứng kiến những khoảnh khắc biểu diễn bùng nổ cùng những thước phim hậu trường chân thực, gần gũi.',103,'8.5','T13 (Từ đủ 13 tuổi trở lên)','2025-11-11','2025-12-22',NULL,'/assets/images/movies/g_dragon_in_cinema/poster_doc.jpg','/assets/images/movies/g_dragon_in_cinema/poster_ngang.jpg','https://youtu.be/r9dVQC_UjBo?si=Ry864i8j3--94z1J',1,'now','Tiếng Hàn | Phụ đề Tiếng Việt'),(17,'Bẫy Tiền','Bẫy Tiền','Phim xoay quanh Đăng Thức - một nhân viên tài chính tưởng chừng có cuộc sống ổn định, bỗng chốc bị cuốn vào một vòng xoáy nguy hiểm. Mọi chuyện bắt đầu từ một vụ lừa đảo qua điện thoại bất ngờ ập đến, khiến cuộc sống của anh đảo lộn. Đăng Thức phải đối mặt với những lựa chọn khó khăn giữa tiền bạc, tình thân và niềm tin, nơi mỗi quyết định đều phải đánh đổi bằng chính những người anh yêu thương.',NULL,'0',NULL,'2025-11-21','2026-01-01',NULL,'/assets/images/movies/bay_tien/poster_doc.jpg','/assets/images/movies/bay_tien/poster_ngang.jpg','https://youtu.be/0wuVwkK-Vsc?si=e4WvUPwUPqJaUpwn',1,'soon','Tiếng Việt | Phụ đề Tiếng Anh'),(18,'Phi Vụ Động Trời 2','Zootopia 2','\"Phi Vụ Động Trời 2\" (Zootopia 2) tiếp tục câu chuyện về cặp đôi cảnh sát thỏ Judy Hopps và cáo Nick Wilde, những người đã trở thành cộng sự chính thức tại Sở Cảnh sát Zootopia. Mối quan hệ hợp tác của họ đối mặt với thử thách mới khi một con rắn bí ẩn tên Gary De\'Snake xuất hiện, gây náo loạn thành phố. Để phá án, Judy và Nick buộc phải thâm nhập vào những khu vực hoàn toàn mới của Zootopia, bao gồm cả Chợ Đầm lầy (Marsh Market), và làm việc bí mật để điều tra một âm mưu lớn hơn.',120,'0',NULL,'2025-11-26','2026-01-06',NULL,'/assets/images/movies/phi_vu_dong_troi_2/poster_doc.jpg','/assets/images/movies/phi_vu_dong_troi_2/poster_ngang.jpg','https://youtu.be/EutV2x9GEZo?si=1sKRDXkpUXwyukGr',1,'soon','Tiếng Anh | Phụ đề Tiếng Việt'),(19,'Phòng Trọ Ma Bầu','Phòng Trọ Ma Bầu','Hai người bạn thân thuê một căn phòng trọ cũ kỹ, nơi liên tục xảy ra những hiện tượng kỳ bí. Trong hành trình tìm hiểu sự thật, họ đối mặt với hồn ma của một người phụ nữ mang thai – \"ma bầu\". Ẩn sau nỗi ám ảnh rùng rợn là một bi kịch và câu chuyện cảm động về tình yêu mẫu tử thiêng liêng, nơi sự hy sinh của người mẹ trở thành sợi dây kết nối những thế hệ.',120,'0',NULL,'2025-11-28','2026-01-08',NULL,'/assets/images/movies/phong_tro_ma_bau/poster_doc.jpg','/assets/images/movies/phong_tro_ma_bau/poster_ngang.jpg','https://youtu.be/jgZM5IhnzDA?si=QKyRFWWiJAO1TT4a',1,'soon','Tiếng Việt | Phụ đề Tiếng Anh'),(20,'Hoàng Tử Quỷ','Hoàng Tử Quỷ','Thân Đức - một hoàng tử được sinh ra nhờ tà thuật, mang trong mình tham vọng trở thành Quỷ Xương Cuồng. Sau khi trốn thoát khỏi cung cấm, Thân Đức tìm cách giải thoát Quỷ Xương Cuồng khỏi Ải Mắt Người để khôi phục giáo phái hắc ám. Để ngăn chặn âm mưu này, một nhóm người phải đối đầu với thế lực tà thuật và tham vọng đẫm máu của kẻ nửa người nửa quỷ. ',NULL,'0',NULL,'2025-12-05','2026-01-15',NULL,'/assets/images/movies/hoang_tu_quy/poster_doc.jpg','/assets/images/movies/hoang_tu_quy/poster_ngang.jpg','https://youtu.be/Qzymh0WVyN8?si=-tGoQp2pYnLSAtju',1,'soon','Tiếng Việt | Phụ đề Tiếng Anh'),(21,'Năm Đêm Kinh Hoàng 2','Five Nights at Freddy\'s 2','Phim lấy bối cảnh một năm sau cơn ác mộng siêu nhiên tại tiệm Pizza Freddy Fazbear. Cựu nhân viên bảo vệ Mike cố gắng giữ bí mật về số phận những con thú máy khỏi cô em gái Abby 11 tuổi. Tuy nhiên, Abby lén ra ngoài để gặp lại Freddy, Bonnie, Chica và Foxy, vô tình khơi mào hàng loạt sự kiện kinh hoàng mới. Bộ phim hé lộ những bí mật đen tối về nguồn gốc thật sự của Freddy Fazbear\'s Pizza.',120,'0',NULL,'2025-12-05','2026-01-15',NULL,'/assets/images/movies/nam_dem_kinh_hoang_2/poster_doc.jpg','/assets/images/movies/nam_dem_kinh_hoang_2/poster_ngang.jpg','https://youtu.be/HccJNOYMBjM?si=pscIV4qWv7fHceSK',1,'soon','Tiếng Anh | Phụ đề Tiếng Việt'),(22,'Nhà \"Hai\" Chủ','Nhà \"Hai\" Chủ','Một cặp vợ chồng mua một căn nhà mới, tưởng chừng đây là khởi đầu cho cuộc sống yên ổn, hạnh phúc. Tuy nhiên, sự xuất hiện của họ tại ngôi nhà này lại khơi mào cho một \"cuộc chiến không hồi kết\". Sau những bức tường lạnh lẽo của căn nhà ẩn chứa vô số bí mật oan trái và những câu chuyện chưa được hé lộ về \"chủ cũ\" và \"chủ mới\". Bộ phim đào sâu vào những rạn nứt gia đình căng thẳng và thông điệp về việc giữ gìn những giá trị truyền thống để tìm kiếm sự bình an trong cuộc sống hiện đại.',NULL,'0',NULL,'2025-12-05','2026-01-15',NULL,'/assets/images/movies/nha_hai_chu/poster_doc.jpg','/assets/images/movies/nha_hai_chu/poster_ngang.jpg','https://youtu.be/ZZZUfZzX0ZU?si=xRMQa03E8Zax0108',1,'soon','Tiếng Việt | Phụ đề Tiếng Anh'),(23,'Avatar 3: Lửa Và Tro Tàn','Avatar 3: Fire and Ash','“Avatar 3: Lửa Và Tro Tàn” tiếp tục câu chuyện gia đình Sully và hành trình khám phá Pandora. Phần phim giới thiệu \"Tộc Lửa\", một bộ lạc Na\'vi hung dữ sống ở vùng núi lửa, mang đến khía cạnh đen tối hơn cho thế giới này. Jake và Neytiri phải đối mặt với những thách thức mới khi đạo diễn James Cameron hứa hẹn sẽ \"đảo ngược tình thế\" và mở rộng đáng kể vũ trụ Na\'vi.',NULL,'0',NULL,'2025-12-19','2026-01-29',NULL,'/assets/images/movies/avatar_3_lua_va_tro_tan/poster_doc.jpg','/assets/images/movies/avatar_3_lua_va_tro_tan/poster_ngang.jpg','https://youtu.be/nb_fFj_0rq8?si=gNKJvIbJP3NymfFS',1,'soon','Tiếng Anh | Phụ đề Tiếng Việt'),(24,'Đồi Gió Hú','Wuthering Heights','Câu chuyện về tình yêu mãnh liệt nhưng đầy hủy diệt giữa Heathcliff và Catherine Earnshaw. Tình yêu của họ bị chia cắt bởi định kiến giai cấp, khiến Heathcliff trở về với dã tâm trả thù tàn khốc. Bản phim này hứa hẹn giữ nguyên sự hỗn loạn cảm xúc nguyên thủy của tác phẩm gốc nhưng thêm thắt yếu tố kinh dị Gothic.',NULL,'0',NULL,'2026-03-13','2026-04-23',NULL,'/assets/images/movies/doi_gio_hu/poster_doc.jpg','/assets/images/movies/doi_gio_hu/poster_ngang.jpg','https://youtu.be/TjAJ7cOjwjg?si=OEUP3OR4lWQQMTxo',1,'soon','Tiếng Anh | Phụ đề Tiếng Việt'),(25,'Không Bông Tuyết Nào Trong Sạch','하얀 차를 탄 여자','Ai rồi cũng nói dối… Một rạng sáng sau đêm bão tuyết, Do Kyung (Jung Ryeo-won) hốt hoảng lái xe đưa chị gái mình đến bệnh viện trong tình trạng đẫm máu. Ngay sau đó, nữ cảnh sát Hyun Joo (Lee Jung-eun) có mặt tại hiện trường và nhanh chóng cảm nhận được rằng sau những lời khai rối ren của Do-kyung là một sự thật đang bị che giấu. Khi mỗi người kể lại vụ việc theo một góc nhìn khác nhau, ranh giới giữa sự thật và dối trá dần tan biến – để lộ một bức tranh tâm lý u tối, rùng mình. Đêm tuyết phủ khiến mọi dấu vết đều biến mất, vậy ai mới thực sự là kẻ thủ ác?',108,'8.0','T16 (Từ đủ 16 tuổi trở lên)','2025-11-14','2025-12-25',NULL,'/assets/images/movies/khong_bong_tuyet_nao_trong_sach/poster_doc.jpg','/assets/images/movies/khong_bong_tuyet_nao_trong_sach/poster_ngang.jpg','https://youtu.be/VMve-FszDFw?si=iJA2i5A392UfTNZA',1,'now','Tiếng Hàn – Phụ đề Tiếng Việt'),(26,'Sư Thầy Gặp Sư Lầy','Will You Marry Monk?','Nhà sư nghiêm khắc Luang Phi Pae sang Nhật để dự đám cưới em gái. Tại đây, ông phát hiện vị hôn phu của em gái là Phra Chin, một nhà sư người Nhật từng là xã hội đen. Luang Phi Pae không chấp nhận việc này và tìm mọi cách chia rẽ cặp đôi. Hàng loạt tình huống hài hước, oái oăm đã xảy ra vì những khác biệt văn hóa và quan điểm. Phim mang đến tiếng cười nhưng cũng truyền tải thông điệp về sự chấp nhận và tình cảm gia đình.',90,'8.2','T16 (Từ đủ 16 tuổi trở lên)','2025-11-14','2025-12-25',NULL,'/assets/images/movies/su_thay_gap_su_lay/poster_doc.jpg','/assets/images/movies/su_thay_gap_su_lay/poster_ngang.jpg','https://youtu.be/ny6xpuuotKE?si=1_aSVvSKjCqhPfOf',1,'now','Tiếng Thái – Phụ đề Tiếng Việt, lồng tiếng Việt'),(27,'Núi Tế Vong','Haunted Mountain: The Yellow Taboo','Ở Đài Loan có một câu nói truyền miệng nổi tiếng về khu rừng dưới Núi Ngọc Sơn, rằng: “Nếu chẳng may lạc trong rừng mà thấy bóng người mặc áo mưa màu vàng thì tuyệt đối đừng đi theo.” Gia Minh (Lưu Dĩ Hào đóng), Ngọc Hân (Viên Lễ Lâm đóng) và An Vĩ (Tào Hựu Ninh đóng) là những người bạn thân trong câu lạc bộ leo núi ở trường đại học. Trong một chuyến leo núi, thay vì đi theo lộ trình ban đầu thì cả 3 lại liều lĩnh bước vào khu vực cấm đã được cảnh báo trong rừng và bị lạc đường. Mặc dù đã buộc những dải vải trắng dọc đường làm ký hiệu, nhưng họ vẫn cứ loanh quanh trở về nơi cũ như thể bị mắc kẹt trong một vòng lặp vô tận. Giữa lúc hỗn loạn, một bóng người mặc áo mưa màu vàng xuất hiện mơ hồ trong sương mù dày đặc mang lại hy vọng cho ba người. Không ngờ, những hiện tượng kỳ lạ liên tiếp xảy ra sau đó mới là bị kịch thật sự.',89,'8.5','T16 (Từ đủ 16 tuổi trở lên)','2025-11-14','2025-12-25','2025-11-12','/assets/images/movies/nui_te_vong/poster_doc.jpg','/assets/images/movies/nui_te_vong/poster_ngang.jpg','https://youtu.be/Nof1hd5-WJU?si=AlZi3MDiBSwWGnfo',1,'now','Tiếng Trung Quốc – Phụ đề Tiếng Việt'),(28,'Chú Thuật Hồi Chiến 0 - Tái Khởi Chiếu','Gekijō-ban Jujutsu Kaisen Zero','Chú Thuật Hồi Chiến 0 là phần anime điện ảnh chuyển thể từ tập tiền truyện [Chú Thuật Hồi Chiến (0) - Trường chuyên Chú Thuật Tokyo]. Khác với phần anime dài tập quen thuộc với Itadori cùng nhóm bạn, phần tiền truyện này sẽ xoay quanh một nhân vật chính khác - chàng thiếu niên bị nguyền rủa Okkotsu Yuta. Khi lời nguyền ếm lên cậu trở thành mối nguy cho xã hội, Yuta đã bị bắt giữ và buộc phải nhập học tại ngôi trường đào tạo Chú Thuật sư. Điều gì đang chờ đón cậu phía trước trong thế giới Chú Thuật đầy hiểm nguy này?',105,'8.6','T13 (Từ đủ 13 tuổi trở lên)','2025-11-14','2025-12-25',NULL,'/assets/images/movies/chu_thuat_hoi_chien_0/poster_doc.jpg','/assets/images/movies/chu_thuat_hoi_chien_0/poster_ngang.jpg','https://youtu.be/ceqa2pIN9ng?si=0qlkgLoCdcdO3hOc',1,'now','Tiếng Nhật – Phụ đề Tiếng Việt'),(29,'GODZILLA MINUS ONE','Gojira Mainasu Wan','Năm 1945, khi Thế chiến thứ Hai đang đi đến hồi kết, phi công Nhật Bản Koichi Shikishima bất ngờ chạm trán một quái vật biển đến từ cõi ngoài, mà người dân trên đảo Odo gọi là Godzilla. Bị giày vò bởi nỗi tội lỗi của kẻ sống sót — vì không thể bắn hạ con quái vật bằng súng gắn trên máy bay, và vì đã bỏ lại nhiệm vụ cảm tử của mình — Shikishima tìm được chút niềm an ủi mong manh bên Noriko, một người phụ nữ sống sót sau các đợt không kích Tokyo, và Akiko, một bé gái mồ côi. Năm tháng trôi qua, Shikishima dần mở lòng với Noriko và những người xung quanh. Nhưng bóng ma quá khứ — lần chạm trán năm xưa với Godzilla, nay đã biến đổi và nhiễm phóng xạ — lại một lần nữa trỗi dậy, khi toàn bộ nước Nhật chìm trong tuyệt vọng và kinh hoàng.',126,'8.8','T13 (Từ đủ 13 tuổi trở lên)','2025-11-07','2025-12-18',NULL,'/assets/images/movies/godzilla_minus_one/poster_doc.jpg','/assets/images/movies/godzilla_minus_one/poster_ngang.jpg','https://youtu.be/ZctQf1MbyBQ?si=qVVQNLN0SeDm77-H',1,'now','Tiếng Nhật – Phụ đề Tiếng Việt');
/*!40000 ALTER TABLE `movie` ENABLE KEYS */;
UNLOCK TABLES;

